def test_seconds_of():
    assert seconds_of('1:02:03') == 3723
    assert seconds_of('0:00:00') == 0
    assert seconds_of('45:10') == 2710
    assert seconds_of('12:59:59') == 46799


def test_seconds_of_depends_on_every_field():
    assert seconds_of('1:00:00') != seconds_of('0:00:01')
    assert seconds_of('0:01:00') != seconds_of('0:00:01')


def test_seconds_of_refuses_what_is_not_a_duration():
    for bad in ('', '1:2:3:4', '1:60:00', '1:00:60', 'a:00:00', '-1:00:00', '1:-5:00'):
        with pytest.raises(ValueError):
            seconds_of(bad)
